<script setup>
import { computed, ref } from 'vue'
const props = defineProps({ modelValue: { type: Array, default: () => [] }, documents: { type: Array, default: () => [] }, disabled: Boolean })
const emit = defineEmits(['update:modelValue', 'refresh'])
const dialog = ref(null), draft = ref([]), query = ref('')
const selected = computed(() => props.documents.filter(d => props.modelValue.includes(d.id)))
const matches = computed(() => props.documents.filter(d => `${d.title} ${d.filename}`.toLowerCase().includes(query.value.toLowerCase())))
function open() { draft.value = [...props.modelValue]; query.value = ''; emit('refresh'); dialog.value.showModal() }
function apply() { emit('update:modelValue', [...draft.value]); dialog.value.close() }
function searchKeydown(event) { if (event.key === 'Enter' && !event.isComposing && event.keyCode !== 229) event.preventDefault() }
</script>
<template>
  <div class="document-picker"><button type="button" class="button" :disabled="disabled" @click="open">添加资料{{ modelValue.length ? `（${modelValue.length}）` : '' }}</button><span v-for="d in selected" :key="d.id" class="selected-document" :title="d.title">{{ d.title }}<button type="button" :disabled="disabled" :aria-label="`移除资料 ${d.title}`" @click="emit('update:modelValue', modelValue.filter(id => id !== d.id))">×</button></span>
    <dialog ref="dialog" aria-labelledby="document-picker-title" class="document-picker-dialog"><header><h2 id="document-picker-title">选择检索资料</h2><button type="button" class="button" @click="dialog.close()">关闭</button></header><p>本轮最多选择 3 篇；留空时检索整个知识库。仅本地资料可阅读，允许云端处理后才能用于模型回答。</p><input v-model="query" placeholder="按文献标题搜索" aria-label="搜索可添加的资料" @keydown="searchKeydown" /><div class="picker-tools"><RouterLink to="/documents?upload=1" target="_blank" rel="noopener noreferrer">上传新文献 ↗</RouterLink><button type="button" class="button" @click="emit('refresh')">刷新列表</button><button type="button" class="button" @click="draft = []">清空选择</button></div>
      <div class="picker-list"><label v-for="d in matches" :key="d.id" :class="{ unavailable: !d.cloud_allowed }"><input v-model="draft" type="checkbox" :value="d.id" :disabled="!d.cloud_allowed || (draft.length >= 3 && !draft.includes(d.id))" :aria-label="`选择文献 ${d.title}`" /><span><strong>{{ d.title }}</strong><small>{{ d.page_count ? `${d.page_count} 页 · ` : '' }}{{ d.cloud_allowed ? '可用于模型回答' : '仅本地，请先在文献管理中修改许可' }}</small></span></label><p v-if="!matches.length">没有匹配的文献，可先上传后刷新列表。</p></div><footer><small>已选 {{ draft.length }} / 3 篇</small><button type="button" class="button primary" @click="apply">应用所选资料</button></footer></dialog>
  </div>
</template>
<style scoped>
.document-picker{display:flex;align-items:center;flex-wrap:wrap;gap:7px;min-width:0}.selected-document{display:flex;align-items:center;max-width:230px;gap:8px;font-size:11px;color:#526991;background:#f2f5fc;border:1px solid #e2e8f3;padding:4px 8px;border-radius:6px;overflow:hidden;white-space:nowrap;text-overflow:ellipsis}.selected-document button{border:0;background:none;color:inherit;cursor:pointer;padding:0 2px}.document-picker-dialog{width:min(760px,94vw);height:min(700px,88vh);box-sizing:border-box;border:1px solid var(--line);border-radius:14px;padding:22px;color:#26354f;background:white;overflow:hidden}.document-picker-dialog[open]{display:flex;flex-direction:column;gap:10px}.document-picker-dialog::backdrop{background:rgb(20 33 60 / .4)}header,footer,.picker-tools{display:flex;justify-content:space-between;align-items:center;gap:10px;flex-shrink:0}header h2{font-size:20px;margin:0}.document-picker-dialog p{font-size:12px;color:var(--muted);line-height:1.8;margin:0}.document-picker-dialog>input{width:100%;box-sizing:border-box;padding:10px;border:1px solid var(--line);border-radius:7px;font:inherit}.picker-tools{justify-content:flex-start;font-size:12px}.picker-tools .button{padding:6px 10px;font-size:11px}.picker-list{flex:1;overflow:auto;min-height:70px;border:1px solid var(--line);border-radius:8px}.picker-list label{display:flex;gap:12px;padding:13px 12px;border-bottom:1px solid var(--line);cursor:pointer}.picker-list input{width:16px;height:16px;margin:3px 0;flex:none}.picker-list strong{display:block;font-size:12px;line-height:1.7;overflow-wrap:anywhere}.picker-list small{font-size:10px;color:var(--muted);display:block;margin-top:4px}.unavailable{opacity:.55}.document-picker-dialog footer small{font-size:12px;color:var(--muted)}@media(max-width:600px){.document-picker-dialog{padding:16px}.selected-document{max-width:180px}.picker-tools{flex-wrap:wrap}}
</style>
